// Short-lived in-memory cache for the main inventory query (5 seconds)
// Prevents duplicate queries from InventoryStats + InventoryInsightBar firing simultaneously
const inventoryQueryCache = new Map<string, { data: unknown; expiry: number }>();
const INVENTORY_CACHE_TTL = 5000;

function getInventoryCache<T>(key: string): T | null {
  const entry = inventoryQueryCache.get(key);
  if (entry && entry.expiry > Date.now()) return entry.data as T;
  inventoryQueryCache.delete(key);
  return null;
}

function setInventoryCache<T>(key: string, data: T): void {
  inventoryQueryCache.set(key, { data, expiry: Date.now() + INVENTORY_CACHE_TTL });
  // Clean up old entries periodically
  if (inventoryQueryCache.size > 50) {
    for (const [k, v] of inventoryQueryCache) {
      if (v.expiry <= Date.now()) inventoryQueryCache.delete(k);
    }
  }
}

type SearchParams = {
  query?: string;
  status?: string;
  category?: string;
  gemType?: string;
  color?: string;
  vendorId?: string;
  collectionId?: string;
  rashiId?: string;
  weightRange?: string;
  filter?: string;
  page?: string;
};

type InventoryListItem = Inventory & {
  media: { id: string; createdAt: Date; type: string; inventoryId: string; mediaUrl: string; isPrimary: boolean }[];
  categoryCode?: { name: string; code: string } | null;
  gemstoneCode?: { name: string; code: string } | null;
  colorCode?: { name: string; code: string } | null;
  cutCode?: { name: string; code: string } | null;
  collectionCode?: { name: string } | null;
  rashis?: { name: string }[];
  certificates?: { name: string; remarks?: string | null }[];
};

export const metadata: Metadata = {
  title: "Inventory | KhyatiGems",
};

const ITEMS_PER_PAGE = 50;

function parseMulti(value: string | undefined): string[] {
  if (!value) return [];
  return value
    .split(",")
    .map((v) => v.trim())
    .filter(Boolean);
}

function buildInventoryWhere(
  params: SearchParams,
  options: { strictRelations: boolean }
): Prisma.InventoryWhereInput {
  const and: Prisma.InventoryWhereInput[] = [];
  const direct: Prisma.InventoryWhereInput = {};
  const query = params.query?.trim();

  if (query) {
    and.push({
      OR: [
        { sku: { contains: query } },
        { itemName: { contains: query } },
        { category: { contains: query } },
        { gemType: { contains: query } },
        { color: { contains: query } },
      ],
    });
  }

  if (params.status && params.status !== "ALL") direct.status = params.status;

  const vendorIds = parseMulti(params.vendorId).filter((v) => v !== "ALL");
  if (vendorIds.length > 0) direct.vendorId = { in: vendorIds };

  const categories = parseMulti(params.category).filter((v) => v !== "ALL");
  if (categories.length > 0) {
    if (options.strictRelations) {
      and.push({
        OR: [
          { category: { in: categories } },
          { categoryCode: { is: { name: { in: categories } } } },
        ],
      });
    } else {
      direct.category = { in: categories };
    }
  }

  const gemTypes = parseMulti(params.gemType).filter((v) => v !== "ALL");
  if (gemTypes.length > 0) {
    if (options.strictRelations) {
      and.push({
        OR: [
          { gemType: { in: gemTypes } },
          { gemstoneCode: { is: { name: { in: gemTypes } } } },
        ],
      });
    } else {
      direct.gemType = { in: gemTypes };
    }
  }

  const colors = parseMulti(params.color).filter((v) => v !== "ALL");
  if (colors.length > 0) {
    if (options.strictRelations) {
      and.push({
        OR: [
          { color: { in: colors } },
          { colorCodeId: { in: colors } },
          { colorCode: { is: { name: { in: colors } } } },
        ],
      });
    } else {
      direct.OR = [{ color: { in: colors } }, { colorCodeId: { in: colors } }];
    }
  }

  if (options.strictRelations) {
    if (params.collectionId && params.collectionId !== "ALL") {
      direct.collectionCodeId = params.collectionId;
    }
    if (params.rashiId && params.rashiId !== "ALL") {
      direct.rashis = { some: { id: params.rashiId } };
    }
  }

  if (params.weightRange && params.weightRange !== "ALL") {
    const [minRaw, maxRaw] = params.weightRange.split("-");
    const min = Number(minRaw);
    const max = Number(maxRaw);
    if (Number.isFinite(min) && maxRaw === "plus") {
      direct.weightValue = { gte: min };
    } else if (Number.isFinite(min) && Number.isFinite(max)) {
      direct.weightValue = { gte: min, lte: max };
    }
  }

  if (params.filter === "preparedUnlisted") {
    and.push(buildPreparedUnlistedWhere());
  } else if (params.filter === "unlisted") {
    and.push({ status: "IN_STOCK", listings: { none: activeChannelListingWhere } });
  } else if (params.filter === "missingImages") {
    and.push({ imageUrl: null, status: "IN_STOCK", media: { none: {} } });
  } else if (params.filter === "readyToSell") {
    and.push(buildReadyToSellWhere());
  } else if (params.filter === "missingCertification") {
    and.push({
      status: "IN_STOCK",
      AND: [
        { OR: [{ imageUrl: { not: null } }, { media: { some: {} } }] },
        {
          AND: [
            {
              OR: [
                { certificateNo: null },
                { certificateNo: "" },
              ],
            },
            {
              OR: [
                { certificateNumber: null },
                { certificateNumber: "" },
              ],
            },
          ],
        },
      ],
    } as Prisma.InventoryWhereInput);
  } else if (params.filter === "highValueUnsold") {
    and.push({ sellingPrice: { gt: 100000 }, status: "IN_STOCK", hideFromAttention: false, updatedAt: { lt: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) } });
  } else if (params.filter === "stagnant") {
    and.push({ status: "IN_STOCK", hideFromAttention: false, createdAt: { lt: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) } });
  } else if (params.filter === "newArrivals") {
    and.push({ status: "IN_STOCK", createdAt: { gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) } });
  } else if (params.filter === "missingHsn") {
    and.push({ status: "IN_STOCK", hideFromAttention: false, OR: [{ hsnCode: null }, { hsnCode: "" }] });
  } else if (params.filter === "todayItems") {
    const startOfToday = new Date();
    startOfToday.setHours(0, 0, 0, 0);
    and.push({ createdAt: { gte: startOfToday } });
  }

  if (Object.keys(direct).length > 0) and.push(direct);
  return and.length ? { AND: and } : {};
}

async function getInventoryData(params: SearchParams) {
  // Start independent work up front so auth, table probes and the query overlap.
  const sessionPromise = auth();
  const tableFlagsPromise = Promise.all([
    hasTable("InventoryMedia"),
    hasTable("CategoryCode"),
    hasTable("GemstoneCode"),
    hasTable("ColorCode"),
    hasTable("CutCode"),
    hasTable("CollectionCode"),
    hasTable("RashiCode"),
    hasTable("_InventoryToRashiCode"),
    hasTable("CertificateCode"),
    hasTable("_CertificateCodeToInventory"),
    hasTable("Vendor"),
  ]);

  const session = await sessionPromise;
  const userId = session?.user?.id;

  let canView = false;
  let canCreate = false;
  let canManageAttentionVisibility = false;

  if (userId) {
    const perms = await checkUserPermissions(userId, [
      PERMISSIONS.INVENTORY_VIEW,
      PERMISSIONS.INVENTORY_CREATE,
      PERMISSIONS.INVENTORY_EDIT,
    ]);
    canView = perms.get(PERMISSIONS.INVENTORY_VIEW) ?? false;
    canCreate = perms.get(PERMISSIONS.INVENTORY_CREATE) ?? false;
    canManageAttentionVisibility = perms.get(PERMISSIONS.INVENTORY_EDIT) ?? false;
  }

  if (!canView) {
    return {
      canView,
      canCreate,
      canManageAttentionVisibility,
      inventory: [] as InventoryListItem[],
      totalItems: 0,
      categories: [],
      gemstones: [],
      colors: [],
      vendors: [],
      collections: [],
      rashis: [],
      certificates: [],
      exportData: [],
      totalPages: 1,
      currentPage: 1,
      filtersKey: "",
    };
  }

  const currentPage = Math.max(1, parseInt(params.page || "1", 10) || 1);
  const filtersKey = JSON.stringify({ ...params, page: currentPage });

  const [
    canMedia,
    canCategoryCode,
    canGemstoneCode,
    canColorCode,
    canCutCode,
    canCollectionCode,
    canRashiCode,
    canInventoryToRashi,
    canCertificateCode,
    canCertificateToInventory,
    canVendor,
  ] = await tableFlagsPromise;

  const canRashi = canRashiCode && canInventoryToRashi;
  const canCertificate = canCertificateCode && canCertificateToInventory;
  const select: Prisma.InventorySelect = {
    id: true,
    sku: true,
    itemName: true,
    internalName: true,
    category: true,
    gemType: true,
    color: true,
    shape: true,
    dimensionsMm: true,
    weightValue: true,
    weightUnit: true,
    weightRatti: true,
    carats: true,
    pieces: true,
    pricingMode: true,
    costPrice: true,
    sellingPrice: true,
    sellingRatePerCarat: true,
    flatSellingPrice: true,
    profit: true,
    status: true,
    condition: true,
    stockLocation: true,
    hideFromAttention: true,
    vendorId: true,
    notes: true,
    certification: true,
    certificateNo: true,
    certificateNumber: true,
    lab: true,
    certificateLab: true,
    createdAt: true,
    updatedAt: true,
    media: {
      orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
      take: 1,
      select: { id: true, createdAt: true, type: true, inventoryId: true, mediaUrl: true, isPrimary: true },
    },
  };

  if (canMedia) {
    select.media = {
      orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
      take: 1,
      select: { id: true, createdAt: true, type: true, inventoryId: true, mediaUrl: true, isPrimary: true },
    };
  }
  if (canCategoryCode) select.categoryCode = { select: { name: true, code: true } };
  if (canGemstoneCode) select.gemstoneCode = { select: { name: true, code: true } };
  if (canColorCode) select.colorCode = { select: { name: true, code: true } };
  if (canCutCode) select.cutCode = { select: { name: true, code: true } };
  if (canCollectionCode) select.collectionCode = { select: { name: true } };
  if (canRashi) select.rashis = { select: { name: true } };
  if (canCertificate) select.certificates = { select: { name: true, remarks: true } };

  let where = buildInventoryWhere(params, { strictRelations: true });

  // For missingHsn filter, exclude categories that have GPIS HSN mapping
  if (params.filter === "missingHsn") {
    try {
      const gpisRow = await (prisma as unknown as { gpisSettings: { findFirst: (args?: Record<string, unknown>) => Promise<{ categoryHsnJson?: string | null } | null> } }).gpisSettings.findFirst();
      const raw = gpisRow?.categoryHsnJson;
      if (raw && typeof raw === "string" && raw.trim()) {
        const parsed = JSON.parse(raw) as Record<string, string>;
        const mappedCategories = Object.keys(parsed).filter(Boolean);
        if (mappedCategories.length > 0) {
          where = {
            ...where,
            AND: [...((where as { AND?: Prisma.InventoryWhereInput[] }).AND || []), { category: { notIn: mappedCategories } }],
          };
        }
      }
    } catch { /* ignore — keep original where */ }
  }

  let rows: InventoryListItem[] = [];
  let totalItems = 0;

  const queryCacheKey = JSON.stringify({ where: JSON.stringify(where), currentPage, filtersKey });
  const cachedResult = getInventoryCache<{ rows: InventoryListItem[]; totalItems: number }>(queryCacheKey);

  if (cachedResult) {
    rows = cachedResult.rows;
    totalItems = cachedResult.totalItems;
  } else {
    try {
      const [count, items] = await Promise.all([
        prisma.inventory.count({ where }),
        prisma.inventory.findMany({
          where,
          orderBy: { createdAt: "desc" },
          select,
          skip: (currentPage - 1) * ITEMS_PER_PAGE,
          take: ITEMS_PER_PAGE,
        }),
      ]);
      totalItems = count;
      rows = items as unknown as InventoryListItem[];
      setInventoryCache(queryCacheKey, { rows, totalItems });
    } catch (error) {
      console.error("Inventory fetch failed in strict mode, retrying with direct fields:", error);
    where = buildInventoryWhere(params, { strictRelations: false });
    const safeSelect = { ...select };
    delete safeSelect.categoryCode;
    delete safeSelect.gemstoneCode;
    delete safeSelect.colorCode;
    delete safeSelect.cutCode;
    delete safeSelect.collectionCode;
    delete safeSelect.rashis;
    delete safeSelect.certificates;

    const [count, items] = await Promise.all([
      prisma.inventory.count({ where }),
      prisma.inventory.findMany({
        where,
        orderBy: { createdAt: "desc" },
        select: safeSelect,
        skip: (currentPage - 1) * ITEMS_PER_PAGE,
        take: ITEMS_PER_PAGE,
      }),
    ]);
    totalItems = count;
    rows = (items as unknown as InventoryListItem[]).map((item) => ({
      ...item,
      media: item.media || [],
    }));
    }
  }

  const [
    categories,
    gemstones,
    colors,
    vendors,
    collections,
    rashis,
    certificates,
    cuts,
    originRows,
  ] = await Promise.all([
    canCategoryCode ? cachedMasters.getCategories(prisma)() : Promise.resolve([]),
    canGemstoneCode ? cachedMasters.getGemstones(prisma)() : Promise.resolve([]),
    canColorCode ? cachedMasters.getColors(prisma)() : Promise.resolve([]),
    canVendor ? cachedMasters.getVendors(prisma)() : Promise.resolve([]),
    canCollectionCode ? cachedMasters.getCollections(prisma)() : Promise.resolve([]),
    canRashi ? cachedMasters.getRashis(prisma)() : Promise.resolve([]),
    canCertificate ? cachedMasters.getCertificates(prisma)() : Promise.resolve([]),
    canCutCode ? cachedMasters.getCuts(prisma)() : Promise.resolve([]),
    cachedMasters.getOrigins(prisma)(),
  ]);

  const origins = originRows.map((r) => r.origin);

  const inventory = removeDuplicates(rows, "id");

  return {
    canView,
    canCreate,
    canManageAttentionVisibility,
    inventory,
    totalItems,
    categories,
    gemstones,
    colors,
    vendors,
    collections,
    rashis,
    certificates,
    cuts,
    origins,
    totalPages: Math.max(1, Math.ceil(totalItems / ITEMS_PER_PAGE)),
    currentPage,
    filtersKey,
  };
}

export default async function InventoryPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  const params = await searchParams;
  const data = await getInventoryData(params);

  if (!data.canView) {
    return (
      <div className="p-6">
        <div className="bg-destructive/15 text-destructive border-destructive/20 border px-4 py-3 rounded-md relative">
          <strong className="font-bold">Access Denied!</strong>
          <span className="block sm:inline"> You do not have permission to view inventory.</span>
        </div>
      </div>
    );
  }

  const buildPageUrl = (p: number) => {
    const nextParams = new URLSearchParams();
    for (const [key, value] of Object.entries(params)) {
      if (value && key !== "page") nextParams.set(key, value);
    }
    if (p > 1) nextParams.set("page", String(p));
    return `/inventory${nextParams.toString() ? `?${nextParams.toString()}` : ""}`;
  };

  const activeFilterLabel = params.filter === "preparedUnlisted" ? "Prepared & Unlisted"
    : params.filter === "unlisted" ? "Unlisted Stock"
    : params.filter === "missingImages" ? "Missing Images"
    : params.filter === "readyToSell" ? "Ready to Sell"
    : params.filter === "missingCertification" ? "Missing Certification"
    : params.filter === "highValueUnsold" ? "High-Value Stagnant"
    : params.filter === "stagnant" ? "Stagnant Stock (90+ days)"
    : params.filter === "newArrivals" ? "New Arrivals (30 days)"
    : params.filter === "missingHsn" ? "Missing HSN Code"
    : null;

  return (
    <AnimatedPage>
    <div className="space-y-6">
      <InventorySavedToast />
      <div className="flex flex-col gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Inventory</h1>
          <p className="text-muted-foreground">Manage your inventory items</p>
        </div>

        <div className="flex flex-wrap items-center gap-2 rounded-2xl border bg-card p-3 shadow-sm [&_button]:rounded-xl [&_a[data-slot=button]]:rounded-xl">
          {data.canCreate && (
            <>
              <Button asChild variant="outline">
                <LoadingLink href="/inventory/import">
                  <Upload className="mr-2 h-4 w-4" /> Import
                </LoadingLink>
              </Button>
              <Button asChild>
                <LoadingLink href="/inventory/new">
                  <Plus className="mr-2 h-4 w-4" /> Add Item
                </LoadingLink>
              </Button>
            </>
          )}
          <InventorySummaryExport />
          <ComprehensiveExport />
          <Suspense fallback={null}>
            <InventoryFilteredExport />
          </Suspense>
          <RegenerateEbayButton />
          <RegenerateEtsyButton />
        </div>
      </div>

      <InventoryStats searchParams={params} />

      <div className="bg-card p-4 rounded-2xl border shadow-sm [&_button]:rounded-xl">
        <InventorySearch
          vendors={data.vendors}
          categories={data.categories}
          gemstones={data.gemstones}
          colors={data.colors}
          collections={data.collections}
          rashis={data.rashis}
        />
      </div>

      <InventoryInsightBar />

      {activeFilterLabel && (
        <div className="flex items-center justify-between rounded-lg border border-primary/20 bg-primary/5 px-4 py-2.5">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-foreground">Filtered by: {activeFilterLabel}</span>
            <span className="text-xs text-muted-foreground">({data.totalItems} items)</span>
          </div>
          <LoadingLink href="/inventory" className="text-xs text-primary hover:underline">Clear filter</LoadingLink>
        </div>
      )}

      <div key={data.filtersKey} className="animate-in fade-in duration-200">
        <InventoryView
          data={data.inventory}
          vendors={data.vendors}
          categories={data.categories}
          gemstones={data.gemstones}
          colors={data.colors}
          rashis={data.rashis}
          certificates={data.certificates}
          collections={data.collections}
          cuts={data.cuts}
          origins={data.origins}
          canManageAttentionVisibility={data.canManageAttentionVisibility}
        />

        {data.totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3 border rounded-md bg-gray-50/50 mt-4">
            <div className="text-sm text-gray-500">
              Showing {Math.min((data.currentPage - 1) * ITEMS_PER_PAGE + 1, data.totalItems)} - {Math.min(data.currentPage * ITEMS_PER_PAGE, data.totalItems)} of {data.totalItems}
            </div>
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" asChild disabled={data.currentPage <= 1}>
                <LoadingLink href={buildPageUrl(data.currentPage - 1)} className={data.currentPage <= 1 ? "pointer-events-none opacity-50" : ""}>
                  Prev
                </LoadingLink>
              </Button>
              <span className="text-sm text-gray-600">Page {data.currentPage} of {data.totalPages}</span>
              <Button variant="outline" size="sm" asChild disabled={data.currentPage >= data.totalPages}>
                <LoadingLink href={buildPageUrl(data.currentPage + 1)} className={data.currentPage >= data.totalPages ? "pointer-events-none opacity-50" : ""}>
                  Next
                </LoadingLink>
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
    </AnimatedPage>
  );
}
